<original_code>
#include <iostream>
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <algorithm>
#include <queue>
#include <vector>
using namespace std;
const int INF = 10000000;
const int N = 210;
const int M = 21000;

struct Edge {
    int to, cap, rev;
};

vector<Edge> G[M];
int level[M], iter[M];

void add_edge(int from, int to, int cap) {
    G[from].push_back({to, cap, (int)G[to].size()});
    G[to].push_back({from, 0, (int)G[from].size()-1});
}

int S, T;

void bfs(int s) {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto &e : G[v]) {
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
}

int dfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < (int)G[v].size(); i++) {
        Edge &e = G[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = dfs(s, t, INF)) > 0) {
            flow += f;
        }
    }
}

char grid1[12][12], grid2[12][12];
int sci[12][12], cap[12][12];
int stone[62][12][12];
int dp[62][12][12][12][12];
int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int n, t;

void expand() {
    for (int k = 1; k <= t; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (stone[k-1][i][j] == 1) {
                    stone[k][i][j] = 1;
                } else if (stone[k-1][i][j] == 2) {
                    stone[k][i][j] = 2;
                } else {
                    bool has2 = false;
                    for (int z = 0; z < 4; ++z) {
                        int nx = i + dir[z][0];
                        int ny = j + dir[z][1];
                        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                            if (stone[k-1][nx][ny] == 2) {
                                has2 = true;
                                break;
                            }
                        }
                    }
                    if (has2) stone[k][i][j] = 2;
                }
            }
        }
    }
}

int vis[12][12];
void dfs(int sx, int sy, int cx, int cy, int k) {
    vis[cx][cy] = 1;
    dp[k][sx][sy][cx][cy] = 1;
    if (k >= t || stone[k][cx][cy]) return;
    for (int z = 0; z < 4; ++z) {
        int nx = cx + dir[z][0];
        int ny = cy + dir[z][1];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny]) {
            if (stone[k][nx][ny]) continue;
            dfs(sx, sy, nx, ny, k+1);
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid1[i]+1);
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') stone[0][i][j] = 2;
            else if (grid1[i][j] == 'Y') stone[0][i][j] = 1;
            else sci[i][j] = grid1[i][j] - '0';
        }
    }
    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid2[i]+1);
        for (int j = 1; j <= n; ++j) {
            if (grid2[i][j] >= '0' && grid2[i][j] <= '9')
                cap[i][j] = grid2[i][j] - '0';
        }
    }

    expand();
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (sci[i][j]) {
                memset(vis, 0, sizeof(vis));
                dfs(i, j, i, j, 0);
            }
    for (int k = 1; k <= t; ++k)
        for (int x = 1; x <= n; ++x)
            for (int y = 1; y <= n; ++y)
                for (int nx = 1; nx <= n; ++nx)
                    for (int ny = 1; ny <= n; ++ny)
                        dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];

    S = 0; T = n*n*2 + 1;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            add_edge(S, (i-1)*n + j, sci[i][j]);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            add_edge(n*n + (i-1)*n + j, T, cap[i][j]);
    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int nx = 1; nx <= n; ++nx)
                for (int ny = 1; ny <= n; ++ny)
                    if (sci[x][y] && cap[nx][ny]) {
                        if (dp[t][x][y][nx][ny])
                            add_edge((x-1)*n + y, n*n + (nx-1)*n + ny, INF);
                    }
    int ans = max_flow(S, T);
    printf("%d\n", ans);
    return 0;
}
